SELECT COUNT(*) FROM repair_leave_request
WHERE deleted = 0 AND worker_id = #{workerId}
  AND status IN #{s}
  AND start_time < #{endTime}
  AND end_time > #{startTime}

SELECT 
FROM repair_leave_request l
JOIN repair_worker w ON w.id = l.worker_id
JOIN sys_user u ON u.id = w.user_id
LEFT JOIN sys_user ra ON ra.id = l.review_admin_id
WHERE l.deleted = 0
AND l.worker_id = #{workerId}
AND l.status = #{approvalStatus}
AND l.start_time >= #{startTime}
AND l.start_time <= #{endTime}
ORDER BY l.id DESC

mapper.update:
UPDATE repair_leave_request
SET status = #{approvalStatus}, review_admin_id = #{reviewAdminId}, review_remark = #{reviewRemark}, review_time = #{reviewTime}
WHERE id = #{id} AND deleted = 0 AND status = #{expectedStatus}

mapper.select:
SELECT id FROM repair_leave_request
WHERE deleted = 0 AND status = 1 AND start_time <= #{now} AND end_time > #{now}
  AND (reassign_status = 0 OR (reassign_status = 1 AND update_time < #{staleBefore}))
ORDER BY id
LIMIT #{limit}

mapper.update:
UPDATE repair_leave_request
SET reassign_status = #{reassignStatus}, update_time = NOW()
WHERE id = #{id} AND reassign_status = #{expectedStatus}

mapper.select:
SELECT DISTINCT l.worker_id FROM repair_leave_request l
JOIN repair_worker w ON w.id = l.worker_id AND w.deleted = 0 AND w.work_status = 1
WHERE l.deleted = 0 AND l.status = 1 AND l.end_time <= #{now}
ORDER BY l.worker_id
LIMIT #{limit}

SELECT COUNT(*) FROM repair_leave_request
WHERE deleted = 0 AND status = 1 AND worker_id = #{workerId}
  AND start_time <= #{now} AND end_time > #{now}
